input.command:
bun -e '
const fs=require("fs");
const txt=fs.readFileSync("server/content/scripts/_unpack/225/all.npc","utf8");
const blocks=txt.split(/\n(?=\[)/);
const out=[];
for(const b of blocks){
  const g=(k)=>{const m=b.match(new RegExp("^"+k+"=(.*)$","m"));return m?m[1]:null;};
  const name=g("name"); const vl=+g("vislevel")||0;
  if(!name||vl<20) continue;
  const hp=+g("hitpoints")||0, atk=+g("attack")||0, def=+g("defence")||0, str=+g("strength")||0;
  const hm=g("huntmode"); const id=b.match(/^\[(.*)\]/m)?.[1];
  if(hp<30) continue;
  out.push({id,name,vl,hp,atk,def,str,hm});
}
out.sort((a,b)=> (b.vl*Math.min(1,60/(60+a.def)))- (a.vl*Math.min(1,60/(60+a.def))));
for(const o of out.slice(0,80)) console.log(o.vl,o.hp,("atk"+o.atk),("def"+o.def),("str"+o.str),o.hm,o.name,"["+o.id+"]");
' 2>&1 | head -90

