const eq = await bot.equipItem(/bronze sword/i);
const st = sdk.getState();
const styles = st.combatStyle?.styles?.map((s:any)=>({i:s.index,name:s.name,trains:s.trainsSkills}));
return {eq, styles, weapon: st.combatStyle?.weaponName};

await sdk.sendSetCombatStyle(2);
const before={atk:sdk.getSkillXp('Attack'),str:sdk.getSkillXp('Strength'),hp:sdk.getSkillXp('Hitpoints'),def:sdk.getSkillXp('Defence')};
let kills=0, fails=0;
const end=Date.now()+25000;
while(Date.now()<end){
  const st=sdk.getState();
  if(!st) break;
  const man=st.nearbyNpcs.filter((n:any)=>/^man$/i.test(n.name)&&n.optionsWithIndex.some((o:any)=>/attack/i.test(o.text))).sort((a:any,b:any)=>a.distance-b.distance)[0];
  if(!man){ fails++; await new Promise(r=>setTimeout(r,500)); continue; }
  try{
    const r=await bot.attack(man,4000);
    if(r.success) kills++;
    else fails++;
  }catch(e){fails++;}
}
const after={atk:sdk.getSkillXp('Attack'),str:sdk.getSkillXp('Strength'),hp:sdk.getSkillXp('Hitpoints'),def:sdk.getSkillXp('Defence')};
